function initPageAuth(){userid||(localStorage.setItem("eventId",getUrlParameter("eventId")),localStorage.setItem("pageSource",getUrlParameter("pageSource")),location.href=host+"/auth/proxy-silent.html?scope=snsapi_base&target_url="+host+"/WeixinService/adviser.shtml");queryAdviser()}function queryAdviser(){$.ajax({url:"/WeixinService/queryUserCustService.xhtml",data:{userId:userid},dataType:"json",cache:!1,type:"post",success:function(n){if(n.returnCode=="0000"){var n=n.data;$("#custserPhoto").attr("src",n.custserPhoto);$("#custserName").html(n.custserName);$("#custserMobile").html(n.custserMobile);$("#custserMobile,#custserMobile2").attr("href","tel:"+n.custserMobile);$("#custserNickname").html(n.custserNickname);$("#wxImg").attr("data-src",n.custserPersonalQrCode);$("#custserGraduateSchool").html(n.custserGraduateSchool);$("#custserWorkYear").html(n.custserWorkYear)}else n.returnCode=="1"&&(location.href=host+"/auth/proxy-silent.html?scope=snsapi_base&target_url="+host+"/WeixinService/adviser.shtml")}})}function addWetChat(n){var t=$(n).attr("data-src");$(".qrcode img").attr("src",t);$("#hintDiv").show()}function closeQrcode(){$("#hintDiv").hide()}var urlParams=getUrlParams(),userId="",userid=urlParams.userid?urlParams.userid:localStorage.getItem("userid"),openId="",host=window.location.protocol+"//"+window.location.host,apiHost="";initPageAuth()